using System;
using GhostGPU.Core;
using GhostGPU.Validation.Models;

namespace GhostGPU.Validation.Tests
{
    /// <summary>
    /// Explicit verification against actual recorded native Rhino 8.35 Grasshopper execution
    /// captured in artifacts/validation/native-reference.json and generated by scripts/NativeReference.py.
    /// All numeric assertions use AssertHelper to ensure NaNs cannot silently pass tolerance checks.
    /// </summary>
    public static class NativeReferenceComparisonTests
    {
        public static void RunAll(IGpuSession session, Action<TestResultItem> recordResult)
        {
            TestNativeClosestTie(session, recordResult);
            TestNativeDistanceRepeatLast(session, recordResult);
            TestNativeDistanceLarge1e155(session, recordResult);
            TestNativeAmplitudeNegative(session, recordResult);
            TestNativeAmplitudeZero(session, recordResult);
            TestNativeRemapSingletonMidpoint(session, recordResult);
            TestNativeRemapReversed(session, recordResult);
            TestNativeMeshColoursPattern(session, recordResult);
        }

        private static void TestNativeClosestTie(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'closest_tie' from scripts/NativeReference.py:
                // Query (input 0): Point3d(0, 0, 0)
                // Targets (input 1): [Point3d(-1, 0, 0), Point3d(1, 0, 0)]
                // Distance to both is exactly 1.0. Native Grasshopper Closest Point selects Target 0 at index 0.
                var queries = new[] { new V3(0.0, 0.0, 0.0) };
                var targets = new[] { new V3(-1.0, 0.0, 0.0), new V3(1.0, 0.0, 0.0) };

                using var qBuf = session.UploadPoints(queries);
                using var tBuf = session.UploadPoints(targets);
                using var res = session.ClosestPoints(qBuf, tBuf);

                var outPts = session.DownloadPoints(res.Points);
                var outIdx = session.DownloadIndices(res.Indices);
                var outDst = session.DownloadScalars(res.Distances);

                if (outIdx[0] != 0)
                    throw new Exception($"Native tie mismatch: expected index 0, got {outIdx[0]}");

                AssertHelper.AssertClose(outDst[0], 1.0, 1e-9, "Native distance tie");
                AssertHelper.AssertClose(outPts[0], new V3(-1.0, 0.0, 0.0), 1e-9, "Native tie point");

                record(new TestResultItem
                {
                    Name = "NativeRef_ClosestTie_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 recorded native-reference.json: target index 0, pt (-1,0,0), dist 1.0."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_ClosestTie_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

        private static void TestNativeDistanceRepeatLast(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'distance_repeat_last' from scripts/NativeReference.py:
                // Input 0: [Point3d(0, 0, 0), Point3d(3, 0, 0), Point3d(6, 0, 0)]
                // Input 1: [Point3d(0, 4, 0), Point3d(3, 4, 0)] -> repeats last (3,4,0) for 3rd item
                // Output: [4.0, 4.0, 5.0]
                // Pair 0: (0,0,0) to (0,4,0) -> 4.0
                // Pair 1: (3,0,0) to (3,4,0) -> 4.0
                // Pair 2: (6,0,0) to (3,4,0) -> sqrt((6-3)^2 + (0-4)^2) = sqrt(9+16) = 5.0
                var ptsA = new[] { new V3(0, 0, 0), new V3(3, 0, 0), new V3(6, 0, 0) };
                var ptsB = new[] { new V3(0, 4, 0), new V3(3, 4, 0) };

                using var aBuf = session.UploadPoints(ptsA);
                using var bBuf = session.UploadPoints(ptsB);
                using var dBuf = session.Distance(aBuf, bBuf);

                var dists = session.DownloadScalars(dBuf);
                double[] expected = { 4.0, 4.0, 5.0 };

                if (dists.Length != expected.Length)
                    throw new Exception($"Distance output count mismatch: expected {expected.Length}, got {dists.Length}");

                for (int i = 0; i < expected.Length; i++)
                {
                    AssertHelper.AssertClose(dists[i], expected[i], 1e-9, $"Distance at {i}");
                }

                record(new TestResultItem
                {
                    Name = "NativeRef_DistanceRepeatLast_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 recorded distance outputs [4.0, 4.0, 5.0]."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_DistanceRepeatLast_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

        private static void TestNativeDistanceLarge1e155(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'distance_large' from scripts/NativeReference.py:
                // Input 0: [Point3d(0, 0, 0)]
                // Input 1: [Point3d(1e155, 1e155, 0)]
                // Output: [1.4142135623730952e+155]
                // Point3d.DistanceTo uses Vector3d.GetLengthHelper to scale by max component:
                // 1e155 * Math.Sqrt(1 + 1) = 1.4142135623730952e155!
                var ptsA = new[] { new V3(0, 0, 0) };
                var ptsB = new[] { new V3(1e155, 1e155, 0) };

                using var aBuf = session.UploadPoints(ptsA);
                using var bBuf = session.UploadPoints(ptsB);
                using var dBuf = session.Distance(aBuf, bBuf);

                var dists = session.DownloadScalars(dBuf);
                double expected = 1.4142135623730952e+155;

                AssertHelper.AssertFinite(dists[0], "Large distance 1e155");

                double relErr = Math.Abs((dists[0] - expected) / expected);
                if (relErr > 1e-14)
                    throw new Exception($"Large distance mismatch: expected {expected}, got {dists[0]} (relErr {relErr})");

                record(new TestResultItem
                {
                    Name = "NativeRef_DistanceLarge_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = $"Matches Rhino 8.35 recorded large distance: {expected:E16} without overflow."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_DistanceLarge_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

        private static void TestNativeAmplitudeNegative(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'amplitude_negative' from scripts/NativeReference.py:
                // Input 0: [Vector3d(3, 4, 0)]
                // Input 1: [GH_Number(-10)]
                // Unit vector: (0.6, 0.8, 0.0), multiplied by -10.0 -> (-6.0, -8.0, 0.0)
                // Matches native-reference.json: [[-6.0, -8.0, -0.0]]
                var vecs = new[] { new V3(3.0, 4.0, 0.0) };
                var mags = new[] { -10.0 };

                using var vBuf = session.UploadVectors(vecs);
                using var mBuf = session.UploadScalars(mags);
                using var aBuf = session.Amplitude(vBuf, mBuf);

                var res = session.DownloadVectors(aBuf);

                AssertHelper.AssertClose(res[0], new V3(-6.0, -8.0, 0.0), 1e-9, "Negative amplitude");

                record(new TestResultItem
                {
                    Name = "NativeRef_AmplitudeNegative_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 recorded amplitude negative output (-6.0, -8.0, 0.0)."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_AmplitudeNegative_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

