        private static void TestNativeRemapSingletonMidpoint(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'remap_singleton' from scripts/NativeReference.py:
                // Input 0: [GH_Number(7)]
                // Input 1 (Source Interval): [Interval(7, 7)] -> singleton source interval
                // Input 2 (Target Interval): [Interval(10, 20)] -> target midpoint is 15.0!
                // Native Grasshopper returns Mapped=[15.0] and leaves Clipped=[null] unset.
                // In GH v0.1, Mapped-only avoids unsupported nullable Clipped output.
                var scalars = new[] { 7.0 };
                var bounds = new[] { 7.0, 7.0 };

                using var sBuf = session.UploadScalars(scalars);
                using var bBuf = session.UploadScalars(bounds);
                using var rBuf = session.Remap(sBuf, bBuf, 10.0, 20.0, false);

                var res = session.DownloadScalars(rBuf);
                AssertHelper.AssertClose(res[0], 15.0, 1e-9, "Singleton remap midpoint");

                record(new TestResultItem
                {
                    Name = "NativeRef_RemapSingleton_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 recorded singleton remap output 15.0 (target midpoint). GH v0.1 Mapped output avoids unsupported null Clipped."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_RemapSingleton_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

        private static void TestNativeRemapReversed(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'remap_reversed' from scripts/NativeReference.py:
                // Input 0: [GH_Number(-1), GH_Number(0.25), GH_Number(2)]
                // Input 1: [Interval(0, 1)]
                // Input 2: [Interval(20, 10)] (reversed target!)
                // Input -1.0: unclipped maps to 30.0, clipped to 20.0 (target max)
                // Input 0.25: unclipped maps to 17.5, clipped to 17.5
                // Input 2.0:  unclipped maps to 0.0, clipped to 10.0 (target min)
                // Native Mapped: [30.0, 17.5, 0.0]
                // Native Clipped: [20.0, 17.5, 10.0]
                var bounds = new[] { 0.0, 1.0 };
                var scalars = new[] { -1.0, 0.25, 2.0 };

                using var sBuf = session.UploadScalars(scalars);
                using var bBuf = session.UploadScalars(bounds);

                // Unclipped
                using var unclippedBuf = session.Remap(sBuf, bBuf, 20.0, 10.0, false);
                var unclipped = session.DownloadScalars(unclippedBuf);

                // Clipped
                using var clippedBuf = session.Remap(sBuf, bBuf, 20.0, 10.0, true);
                var clipped = session.DownloadScalars(clippedBuf);

                double[] expUnclipped = { 30.0, 17.5, 0.0 };
                double[] expClipped = { 20.0, 17.5, 10.0 };

                for (int i = 0; i < 3; i++)
                {
                    AssertHelper.AssertClose(unclipped[i], expUnclipped[i], 1e-9, $"Reversed remap unclipped at {i}");
                    AssertHelper.AssertClose(clipped[i], expClipped[i], 1e-9, $"Reversed remap clipped at {i}");
                }

                record(new TestResultItem
                {
                    Name = "NativeRef_RemapReversed_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 reversed domain mapping: Mapped=[30, 17.5, 0], Clipped=[20, 17.5, 10]."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_RemapReversed_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }

        private static void TestNativeMeshColoursPattern(IGpuSession session, Action<TestResultItem> record)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // Native reference case 'mesh_colours_pattern' from scripts/NativeReference.py:
                // Quad mesh (4 vertices) with [Color.Red, Color.Blue]
                // Colours in native-reference.json: [-65536, -16776961, -65536, -16776961]
                // -65536 is 0xFFFF0000 (Red)
                // -16776961 is 0xFF0000FF (Blue)
                // Repeated cyclically over 4 quad vertices
                uint red = unchecked((uint)-65536);
                uint blue = unchecked((uint)-16776961);

                var pattern = new[] { red, blue };
                using var pBuf = session.UploadColours(pattern);
                using var rBuf = session.RepeatColours(pBuf, 4);

                var res = session.DownloadColours(rBuf);
                if (res.Length != 4)
                    throw new Exception("Colours length mismatch.");

                uint[] expected = { red, blue, red, blue };
                for (int i = 0; i < 4; i++)
                {
                    if (res[i] != expected[i])
                        throw new Exception($"Colour at {i} mismatch: expected 0x{expected[i]:X8}, got 0x{res[i]:X8}");
                }

                record(new TestResultItem
                {
                    Name = "NativeRef_MeshColoursPattern_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Pass,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Details = "Matches Rhino 8.35 recorded mesh colour pattern [-65536, -16776961, -65536, -16776961] (Red/Blue)."
                });
            }
            catch (Exception ex)
            {
                record(new TestResultItem
                {
                    Name = "NativeRef_MeshColoursPattern_MatchesRhino8",
                    Category = "NativeReference",
                    Outcome = TestOutcome.Fail,
                    DurationMs = sw.Elapsed.TotalMilliseconds,
                    Message = ex.Message
                });
            }
        }
    }
}
